function variationMath(){var v=changes.variation,cost=Number(v.cost)||0,margin=Math.max(0,Math.min(90,Number(v.margin)||0)),preTax=Math.round(cost/(1-margin/100)),tax=Math.round(preTax*.05);return {cost:cost,margin:margin,preTax:preTax,tax:tax,withTax:preTax+tax,grossProfit:preTax-cost};}
function variationMathHtml(){var m=variationMath();return '<div><small>Incremental direct cost</small><strong>'+cash(m.cost)+'</strong></div><div><small>Target gross margin</small><strong>'+m.margin+'%</strong></div><div><small>Proposed gross profit</small><strong>'+cash(m.grossProfit)+'</strong></div><div><small>Tax estimate (5%)</small><strong>'+cash(m.tax)+'</strong></div><div class="important"><small>Price before tax</small><strong>'+cash(m.preTax)+'</strong></div><div class="important"><small>Total incl. sample tax</small><strong>'+cash(m.withTax)+'</strong></div>';}
function variationGate(label,key,description){var v=changes.variation,done=v[key];return '<div class="queue-row"><span class="row-icon">'+(done?'✓':'○')+'</span><div style="flex:1"><div class="queue-title">'+esc(label)+'</div><div class="queue-sub">'+esc(description)+'</div></div>'+(done?stagePill('Complete'):button('Simulate ↗','variationGate',key,'tiny-button'))+'</div>';}

